Evaluate this query exactly under SQLite semantics. Use JSON integers or null for the values of its single output row, respecting duplicate rows and SQL NULL.
WITH lefts(id,c,x) AS (
 VALUES (1,'p',3),(2,'p',3),(3,'p',NULL),(4,'q',2),(5,'q',5),(6,'r',NULL),(7,NULL,4)
), righted(c,y) AS (
 VALUES ('p',3),('p',3),('p',NULL),('q',2),('q',NULL),('r',NULL),(NULL,4)
), j AS (
 SELECT id,l.c,x,y FROM lefts l LEFT JOIN righted r ON l.c IS r.c
), z AS (
 SELECT * FROM j WHERE y != x OR y IS NULL OR x IS NULL
), w AS (
 SELECT c,COUNT(*) AS sz,SUM(COALESCE(y,0)) AS ys,COUNT(DISTINCT x) AS dx FROM z GROUP BY c
)
SELECT (SELECT SUM(sz) FROM w) AS kept,
       (SELECT SUM(ys) FROM w WHERE sz>=2) AS large_y,
       (SELECT SUM(dx) FROM w) AS distinct_sum,
       (SELECT COUNT(*) FROM lefts WHERE x NOT IN (
           SELECT y FROM righted WHERE c IS lefts.c
        )) AS not_in_rows,
       (SELECT COUNT(*) FROM lefts WHERE NOT EXISTS (
           SELECT 1 FROM righted WHERE c IS lefts.c AND y IS x
        )) AS not_exists_rows,
       (SELECT MAX(ys) FROM w WHERE c IS NULL) AS null_group;
Return only one JSON object with exactly these keys: kept, large_y, distinct_sum, not_in_rows, not_exists_rows, null_group.
